//import { initialState } from '../store/configureStore';
//import { fetchAuth } from '../actions/authActions'

import axios from 'axios';

export const COMMENTERS_MESSAGE_CHANGE = 'COMMENTERS_MESSAGE_CHANGE'

export function handleCommentersMessageChange(event) {
    
    return (dispatch, getState) => {
        
        const { value } = event.target
  
            dispatch({
                type: COMMENTERS_MESSAGE_CHANGE,
                commentersMessage: value
            })
       
        if(getState().commentersMessage && getState().commentersMessage.length > 10) {
            dispatch({
                type: COMMENTERS_MESSAGE_SUBMIT_ENABLE
          })
        } else {
            dispatch({
                type: COMMENTERS_MESSAGE_SUBMIT_DISABLE
          })
        }

          
    }
    
}


export function handleCommentersMessageSubmit(event) {
    
    return (dispatch, getState) => {

    dispatch({
         type: COMMENTERS_MESSAGE_SUBMITTED
       });
           
        axios.get('https://scbm.amfdev.co.uk/api/commenters/', {
         params: {
           commentersMessageUrl: encodeURI(getState().commentersMessageUrl)
         }
         })
         .then(json => catchCommentersMessageNoResults(json.data, dispatch))
         .then(json => catchCommentersMessageOtherError(json, dispatch))
         .then(json => doCommentersMessageSuccess(json, dispatch))
          .catch(error => console.log(error));
                  
    }
    
}

//res.send({success: false, commenterData: "no commenters"})

function catchCommentersMessageNoResults(json, dispatch) {
    console.log('catchCommentersMessageNoResults')
    console.log(json);
    if (json.noResults) {
        dispatch({
                type: COMMENTERS_MESSAGE_NO_RESULTS
              })
        throw Error(json.error);
    }
    
  return json;
}


function catchCommentersMessageOtherError(json, dispatch) {
    console.log('catchCommentersMessageOtherError')
    if (!json.success) {
        dispatch({
                type: COMMENTERS_MESSAGE_OTHER_ERROR
              })
        throw Error(json.error);
    }
    
  return json;
}


function doCommentersMessageSuccess(json, dispatch) {
    console.log('doCommentersMessageSuccess')
 
        dispatch({
                type: COMMENTERS_MESSAGE_SUCCESS,
                commenterData: json.commenterData
              })
  return json;
}


